node.doctext:
Hello,

I have complex XML file (around 1000 of records) and need to retrieve few elements based on the condition...

<p>1.want to read node only where ciType="application" </p>
<p>2.read the value of entry where key="Last Status Change"  o/p:10/2/2017 10:16 PM  </p>

<code>
<nodes>
	<node name="ABC" id="1" ciType="null">
		<children>
			<node name="Business Systems" classification="null" ciType="ci_collection">
					<dimension name="Unresolved Events" status="-2" id="3232">
					</dimension>
					<dimension name="Availability" status="10" id="12313">
					</dimension>
				<children>
					<node name="3YP (421)" classification="null" ciType="application" >
							<dimension name="Availability" status="20" id="2312">
							<body>
							<entry key="Status">
							<![CDATA[ OK  ]]> 
							</entry>
							<entry key="Business Rule">	
							<![CDATA[ Percentage Rule  ]]> 
							</entry>
							<entry key="Last Status Change">
							<![CDATA[ 10/2/2017 10:16 PM  ]]> 
							</entry>
							</body>
							</dimension>
					</node>		
				</children> 
			</node>	
		</children>
	</node>
</nodes>
</code>

<p> sample code </p>

<code>
#!/usr/bin/perl
use strict;
use warnings;
use XML::XPath;
use XML::LibXML::NodeList;
use Data::Dumper;

my @records;

	my $bamxml = 'OpenApi.xml';
	my $bamxp = XML::XPath->new(filename => $bamxml);
	my $bamxpath =  $bamxp->findnodes('//nodes/node/children/node/children/node');
	my $pattern = shift;
	my $matches = XML::LibXML::NodeList->new;

	foreach my $bamnode ($bamxpath->get_nodelist) {

		my $name   = $bamxp->find('./@name',$bamnode)->string_value;
	        my $citype = $bamxp->find('./@ciType',$bamnode)->string_value;
		my $status = $bamxp->find('./dimension/@status',$bamnode)->string_value;
		my $time = $bamxp->find("./dimension/body/entry",$bamnode)->string_value;

		s/^\s+|\s+$//g for $name,$citype,$status,$time;
			push @records, {
				name => $name,
				citype => $citype,
				status => $status,
				Time => $time
			};

	}
</code>

